document.addEventListener("classAdded", function (e) {
    if (e.className.startsWith("lexx_"))
        Lexx_Icon_Refresh(e.element.parentElement || e.element.parentNode());
});

// Crear una función que maneje la inserción de nodos en el DOM
function handleNodeInsertion(mutationsList) {
    mutationsList.forEach(function (mutation) {
        mutation.addedNodes.forEach(function (addedNode) {
            // Tu código para manejar la inserción del nodo aquí
            var cEl = addedNode;
            Lexx_Icon_Refresh(cEl.parentElement || cEl.parentNode);
        });
    });
}

// Crear un observador de mutaciones
var observer = new MutationObserver(handleNodeInsertion);

// Definir las opciones del observador para detectar la inserción de nodos
var config = { childList: true, subtree: true };

// Comenzar a observar la inserción de nodos en el DOM
observer.observe(document, config);

function Lexx_Icon_Refresh(e) {
    setTimeout(function () {
        var R = e?.querySelectorAll(".lexx");
        if (R) {
            Object.keys(R).forEach(function (key) {
                var cO = R[key];
                if (!cO.getAttribute("lic")) {
                    var ArrCL = cO.className.split(" ");
                    var isPro = false;
                    Object.keys(ArrCL).forEach(function (key) {
                        if (ArrCL[key].startsWith("lexx_")) {
                            cO.innerHTML = lexx_icons_src[ArrCL[key]] || "";
                            cO.classList.remove(ArrCL[key]);
                        } else if (ArrCL[key] == "pro") {
                            isPro = true;
                            cO.classList.remove("pro");
                        }
                    });
                    if (isPro) {
                        Slt = cO.querySelectorAll("path");
                        if (Slt.length > 0) {
                            Slt[0].style.opacity = "0.6";
                        }
                    }
                }
            });
        }
    }, 1);
}
Lexx_Icon_Refresh(document);

//Crear Clases Lexx
document.addEventListener("DOMContentLoaded", function () {
    var STL = "";
    var VRS = "";
    var isIE = _.isIE();
    _.each(lexx_icons_src, function (idx, val) {
        var CD = _.svg2img(val);
        if (isIE) {
            STL +=
                "." +
                idx +
                "_b:before{background-image: url(" +
                CD +
                ');background-size:1em 1em;display:inline-block;width:1em;height:1em;content:"";background-repeat: no-repeat;}';
            STL +=
                "." +
                idx +
                "_a:after{background-image: url(" +
                CD +
                ');background-size:1em 1em;display:inline-block;width:1em;height:1em;content:"";background-repeat: no-repeat;}';
        } else {
            VRS += "--" + idx + ": url(" + CD + ");";
            STL +=
                "." +
                idx +
                "_b:before{-webkit-mask-image: var(--" +
                idx +
                ");mask-image: var(--" +
                idx +
                ');-webkit-mask-repeat: no-repeat;mask-repeat: no-repeat;-webkit-mask-size:1em 1em;mask-size:1em 1em;display:inline-block;width:1em;height:1em;content:"";background-color:currentColor;}';
            STL +=
                "." +
                idx +
                "_a:after{-webkit-mask-image: var(--" +
                idx +
                ");mask-image: var(--" +
                idx +
                ');-webkit-mask-repeat: no-repeat;mask-repeat: no-repeat;-webkit-mask-size:1em 1em;mask-size:1em 1em;display:inline-block;width:1em;height:1em;content:"";background-color:currentColor;}';
        }
    });
    var el = document.head.appendChild(document.createElement("link"));
    var blob = new Blob([STL + (VRS ? ":root{" + VRS + "}" : "")], {
        type: "text/css",
    });
    var url = URL.createObjectURL(blob);
    el.rel = "stylesheet";
    el.href = url;
});
